INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ねぇねぇ、騎士クン\n手伝ってあげようよ～", 1001, "お！\nあそこに困ってそうな人発見！", 0, 0, 1.4, 0, 2, 1, 1, 1, "春咲 ひより", "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("わ、わたし、\nなに言ってるんだろ\nあはは…", 1002, "大切な人を\n守れるようになりたい…って", 0, 0, 1.4, 0, 2, 1, 1, 1, "草野 優衣", "みんなみたいに\nわたしも強くならなきゃ", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("少しは磨かれると思いますよ。", 1003, "キミに必要な集中力と感性が", 0, 0, 1.4, 0, 2, 1, 1, 1, "士条 怜", "フェンシングを始めてみては？", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("みそぎはねぇ、\nかくれんぼやりたい！", 1004, "今日はなにして遊ぶ？", 0, 0, 1.5, 0, 2, 1, 1, 1, "穂高 みそぎ", "ねぇ、にいちゃん！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私といっしょに…\nいかない？", 1006, "ねぇ…", 0, 0, 1.4, 0, 2, 1, 1, 1, "風宮 あかり", "風宮あかりです", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("食べ物の恨みは怖いのー", 1007, "プリンたべたいのー", 0, 0, 1.5, 0, 2, 1, 1, 1, "出雲 宮子", "出雲宮子なのー", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("いいよ。\n見られることは運命さ…", 1008, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 0, 1.4, 0, 2, 1, 1, 1, "虹村 雪", "ボクは虹村雪。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("人呼んで「疾風の冥姫」!!", 1009, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 0, 1.4, 0, 2, 1, 1, 1, "柊杏奈", "フッ…聞いて後悔するがいい！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ほんまおおきにやわ～♪", 1010, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 0, 1.5, 0, 2, 1, 1, 1, "姫宮 真歩", "マホマホ王国のプリンセス、\nまほ姫どす", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ここで会ったが\n100年目～！", 1011, "生き別れたお兄ちゃんを探して\n三千世界！", 0, 0, 1.4, 0, 2, 1, 1, 1, "衣之咲 璃乃", "衣之咲璃乃です！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…って、お願い！\n誰にも言わないでおいて～！", 1012, "ち、超能力って…\n何のことかな～？", 0, 0, 1.4, 0, 2, 1, 1, 1, "柏崎 初音", "私はハツネ、\n結構強いんだよ。\nきらーん☆", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ヒデサイまぢ\nGF（グッドフィーリング）～♪", 1016, "一応カリスマ読モJKやってまっす！", 0, 0, 1.4, 0, 2, 1, 1, 1, "美波 鈴奈", "ちょす！\n美波鈴奈だよ～♪", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("でも、沖縄もとってもいいとこさー", 1017, "東京は遊園地みたいなところさー", 0, 0, 1.4, 0, 2, 1, 1, 1, "喜屋武 香織", "はいたーい。\n喜屋武香織さー。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("イオちゃんって呼んでね。", 1018, "先生って呼ばれるのは\nくすぐったいから", 0, 0, 1.4, 0, 2, 1, 1, 1, "支倉 伊緒", "支倉伊緒です。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ミミをおいてかないでぇ～", 1020, "あ！/\お兄ちゃ～ん\nまってよ～", 0, 0, 1.5, 0, 2, 1, 1, 1, "茜 ミミ", "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ふぇぇぇぇぇん……", 1021, "あの……\nふぇ……", 0, 0, 1.5, 0, 2, 1, 1, 1, "栗林 くるみ", "あ…あの…えっと…\n栗…林…くるみ…です……", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("なんてありがとうございます！", 1022, "こんな私に貴重な時間を\n割いていただき、", 0, 0, 1.4, 0, 2, 1, 1, 1, "風宮 より", "風宮よりです。\nあああああ！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私こっち行きたいー\nね、早く早くー", 1023, "おにいちゃんどこいくの？\nえ？", 0, 0, 1.5, 0, 2, 1, 1, 1, "北条 綾音", "私、アヤネ！\nぷうきちと一緒についてってあげるね！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("これて何か違う…\nあああすみません！", 1025, "ふ、不束者ですが\nどうぞ末永く…って、", 0, 0, 1.4, 0, 2, 1, 1, 1, "天野 すずめ", "わっ…わっ…私、\n天野すずめといいます！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("離しませんわ………\n絶対に…!!", 1027, "あなたは…運命の……\n伴侶……", 0, 0, 1.4, 0, 2, 1, 1, 1, "倉石 恵理子", "……クスクス…私は\n…倉石恵理子……", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…そうでしょ？？", 1028, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 0, 1.4, 0, 2, 1, 1, 1, "佐々木 咲恋", "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("あはは、\n私もまだまだだなぁ～", 1029, "ぇっと…\nキミ、私のこと知らないの?!", 0, 0, 1.4, 0, 2, 1, 1, 1, "桜井 望", "桜井望だよ！\nよろしくねっ", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ショーグン、\nワタシと一緒に天下統一デース！", 1030, "初めまして、\n私はニノン・ジュベール申すデス！", 0, 0, 1.4, 0, 2, 1, 1, 1, "ニノン・ジュベール", "デケデケデンっ！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("おかしいですね……", 1031, "でもって私の隣にいるのが……\nえ、見えない？", 0, 0, 1.4, 0, 2, 1, 1, 1, "上喜 しのぶ", "上喜しのぶです。\n手元のドクロが父です。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そう、\nオラのボケに突っ込める相方が…！", 1033, "けんども\nそれには足りないモンが…", 0, 0, 1.5, 0, 2, 1, 1, 1, "野戸まひる", "目指すはビッグな\nお笑い芸人だっぺ！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ちょ\nちょっと一杯飲んできます…！", 1034, "ちょっと緊張しちゃって…", 0, 0, 1.4, 0, 2, 1, 1, 1, "綾瀬 ゆかり", "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("これ以上お話しすることは…\nないです！", 1036, "知らない人とは話しちゃいけないので", 0, 0, 1.5, 0, 2, 1, 1, 1, "氷川 鏡華", "氷川鏡華…です", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("私体が弱いから、\n30分に一度休憩しないと\nいけないんです。", 1038, "……あ、アラーム。", 0, 0, 1.4, 0, 2, 1, 1, 1, "柏崎 栞", "柏崎…栞です。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("野に咲く花が、\n唯一の話相手です。", 1040, "私、一人も友達がいなくて……", 0, 0, 1.4, 0, 2, 1, 1, 1, "双葉 碧", "ふ、双葉碧です。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そう思っています。", 1042, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 0, 1.4, 0, 2, 1, 1, 1, "三角 千歌", "三角千歌です。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("う、疑ってすまなかったな…", 1043, "あぁ？\nお前のそいつの仲間か？", 0, 0, 1.4, 0, 2, 1, 1, 1, "安芸 真琴", "安芸真琴だ。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！", 1044, "生けとし生ける全ての者よ！", 0, 0, 1.4, 0, 2, 1, 1, 1, "イリヤ・オーンスタイン", "わらわこそは夜を総べる者！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("ｌク、クウカに何かご用ですか!?", 1045, "ぐふふふふ……はっ！", 0, 0, 1.4, 0, 2, 1, 1, 1, "遠見 空花", "そこで騎士は妖精を乱暴に……", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("う～ん…\n猫ってホントに最高にゃ～♪", 1046, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 0, 1.4, 0, 2, 1, 1, 1, "宮坂たまき", "宮坂たまきにゃ♪\n猫はいいにゃよ？", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("…と思ったら\nバイトの時間だ！\nまたあとでね！", 1048, "それでは早速クエストに…", 0, 0, 1.4, 0, 2, 1, 1, 1, "大神 美冬", "大神美冬よ！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("お姉ちゃんがぜ～んぶ\nやってあげるからね！", 1049, "クエストもバトルも\n掃除も洗濯も", 0, 0, 1.4, 0, 2, 1, 1, 1, "星野静流", "星野静流だよ！", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("学校では誰もが憧れる\nアイドル的な存在ってやつよ♪", 1050, "見ての通りの\nセクシー美少女で", 0, 0, 1.5, 0, 2, 1, 1, 1, "玉泉美咲", "アタシは玉泉美咲。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("？？？？", 1052, "？？？？", 0, 0, 1.4, 0, 2, 1, 1, 1, "リマ", "？？？", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1053, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 1.5, 0, 2, 1, 1, 1, "モニカ・ヴァイスヴィント", "モニカ・ヴァイスヴィントだ。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1058, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 1.5, 0, 2, 1, 1, 1, "ペコリーヌ", "モニカ・ヴァイスヴィントだ。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1059, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 1.5, 0, 2, 1, 1, 1, "コッコロ", "モニカ・ヴァイスヴィントだ。", 0, 0);
INSERT INTO `v1_b6bc3f9bbc73e6a0b93d13bdd2715586915a42e2218c3ccf278a21a54741c6ab` VALUES ("そ、そこまでいうなら\nもらってやる", 1060, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 1.5, 0, 2, 1, 1, 1, "キャル", "モニカ・ヴァイスヴィントだ。", 0, 0);
